//go:build linux

package xdpguard

import (
	"bytes"
	"context"
	_ "embed"
	"encoding/json"
	"fmt"
	"log"
	"net"
	"net/netip"
	"time"

	"github.com/cilium/ebpf"
	"github.com/cilium/ebpf/link"
	"github.com/cilium/ebpf/rlimit"
)

// filter.o is generated by scripts/build-xdp.sh using clang's BPF target.
//
//go:embed filter.o
var object []byte

type limits struct{ Packets, SYNs, DropFragments uint32 }
type key4 struct {
	Bits uint32
	Addr [4]byte
}
type key6 struct {
	Bits uint32
	Addr [16]byte
}

func load(c Config) (*ebpf.Collection, error) {
	if err := c.Validate(); err != nil {
		return nil, err
	}
	spec, err := ebpf.LoadCollectionSpecFromReader(bytes.NewReader(object))
	if err != nil {
		return nil, err
	}
	collection, err := ebpf.NewCollection(spec)
	if err != nil {
		return nil, fmt.Errorf("load XDP program (Linux 5.15+, BPF privileges required): %w", err)
	}
	success := false
	defer func() {
		if !success {
			collection.Close()
		}
	}()
	zero := uint32(0)
	v := limits{Packets: c.PacketsPerSecond, SYNs: c.SYNsPerSecond}
	if c.DropFragments {
		v.DropFragments = 1
	}
	if err = collection.Maps["config"].Update(&zero, &v, ebpf.UpdateAny); err != nil {
		return nil, err
	}
	one := uint32(1)
	for _, p := range c.Ports {
		proto := uint32(6)
		if p.Protocol == "udp" {
			proto = 17
		}
		key := proto<<16 | uint32(p.Port)
		if err = collection.Maps["ports"].Update(&key, &one, ebpf.UpdateAny); err != nil {
			return nil, err
		}
	}
	for kind, list := range map[string][]string{"block": c.BlockCIDRs, "allow": c.AllowCIDRs} {
		for _, s := range list {
			prefix, _ := netip.ParsePrefix(s)
			prefix = prefix.Masked()
			if prefix.Addr().Is4() {
				key := key4{uint32(prefix.Bits()), prefix.Addr().As4()}
				err = collection.Maps[kind+"4"].Update(&key, &one, ebpf.UpdateAny)
			} else {
				key := key6{uint32(prefix.Bits()), prefix.Addr().As16()}
				err = collection.Maps[kind+"6"].Update(&key, &one, ebpf.UpdateAny)
			}
			if err != nil {
				return nil, err
			}
		}
	}
	success = true
	return collection, nil
}
func Run(ctx context.Context, c Config) error {
	if err := c.Validate(); err != nil {
		return err
	}
	iface, err := net.InterfaceByName(c.Interface)
	if err != nil {
		return err
	}
	if err = rlimit.RemoveMemlock(); err != nil {
		return fmt.Errorf("memlock limit: %w", err)
	}
	collection, err := load(c)
	if err != nil {
		return err
	}
	defer collection.Close()
	mode := link.XDPDriverMode
	if c.Mode == "generic" {
		mode = link.XDPGenericMode
	}
	attached, err := link.AttachXDP(link.XDPOptions{Program: collection.Programs["fess_filter"], Interface: iface.Index, Flags: mode})
	if err != nil {
		return fmt.Errorf("attach XDP without replacing an existing program on %s: %w", c.Interface, err)
	}
	defer attached.Close()
	log.Printf("fess-xdp attached interface=%s mode=%s; only configured TCP/UDP ports are filtered", c.Interface, c.Mode)
	ticker := time.NewTicker(10 * time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return nil
		case <-ticker.C:
			stats := map[string]uint64{}
			for key, name := range []string{"seen", "passed", "cidr_drop", "rate_drop", "fragment_drop", "malformed_pass"} {
				k := uint32(key)
				var values []uint64
				if err := collection.Maps["counters"].Lookup(&k, &values); err != nil {
					return err
				}
				for _, v := range values {
					stats[name] += v
				}
			}
			out, _ := json.Marshal(stats)
			log.Printf("xdp counters=%s", out)
		}
	}
}
